import React, {  useRef, useEffect } from 'react';
import styles from './SettingsModal.module.css';
// importing the theme of the app
import { ColorTheme } from '../../types';

// settings modal 
// lets user change the theme , account preferences etc
// theme working for now

interface Props {
  onClose: () => void;
  onSave: (theme: string) => void;
}

export default function SettingsModal({ onClose, onSave }: Props) {
  const overlayRef = useRef<HTMLDivElement>(null);

  const icon = '⚙️';
  const color = 'themeColor'; // Replace with the actual theme color

    useEffect(() => {
    const handler = (e: KeyboardEvent) => {
        if (e.key === 'Escape') onClose();
    };
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, [onClose]);

  const handleOverlayClick = (e: React.MouseEvent) => {
    if (e.target === overlayRef.current) onClose();
  };

  const handleSave = (theme: string) => {
    onSave(theme);
  }

    return (
    <div className={styles.overlay} ref={overlayRef} onClick={handleOverlayClick}>
      <div className={styles.modal} role="dialog" aria-modal="true">

        {/* Header */}
        <div className={styles.header}> 
            <span className={styles.preview} >
                 {icon}
             </span>

            <span className={styles.title}>Settings</span>
            <button className={styles.closeBtn} onClick={onClose} aria-label="Close settings modal">
                ✕
            </button>
        </div> 

        <div className={styles.body}>
            <div className={styles.field}>
                <label className={styles.label} htmlFor="themeSelect">Theme</label>
            </div>
        </div>

        </div>

    </div>
  );
}
